import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.CnJ-JtFX.js";const g=JSON.parse('{"title":"EP.08 物料不是组件，是一份三方都能读的协议","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.08-lowcode-engine-materials.md","filePath":"comics/EP.08-lowcode-engine-materials.md","lastUpdated":1792683644000}'),c={name:"comics/EP.08-lowcode-engine-materials.md"};function d(s,e,n,i,l,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="ep-08-物料不是组件-是一份三方都能读的协议" tabindex="-1">EP.08 物料不是组件，是一份三方都能读的协议 <a class="header-anchor" href="#ep-08-物料不是组件-是一份三方都能读的协议" aria-label="Permalink to &quot;EP.08 物料不是组件，是一份三方都能读的协议&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/08-lowcode-engine-materials">guide/08-lowcode-engine-materials</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>困境</strong>：标签君写好了 <code>OrderSummary</code> 组件，本地 import 正常，拖进画布却报「这不是一个 React 组件」。</li><li><strong>揭秘</strong>：码叔指出设计器、渲染器、出码器读的是同一份物料描述，缺了包名、导出名、是否解构，渲染器只能拿到整个模块对象。</li><li><strong>实证</strong>：像素酱补上 <code>npm.exportName</code> 与 <code>destructuring</code>，再注册自定义 <code>LabToneSetter</code>，右栏出现「青 / 紫 / 琥珀」三个色调按钮。</li><li><strong>结案</strong>：码叔总结物料三件套——组件实现、元数据、运行时资源；少一项，就会出现「能渲染、不能编辑」的半成品。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-为什么-import-成功-画布却报错" tabindex="-1">第一格：为什么 import 成功，画布却报错 <a class="header-anchor" href="#第一格-为什么-import-成功-画布却报错" aria-label="Permalink to &quot;第一格：为什么 import 成功，画布却报错&quot;">​</a></h3><p>组件在业务代码里能 import，只说明模块系统能找到它。设计器走的是另一条路径：它先读 <code>componentsMap</code>，再按 <code>package + version + exportName</code> 去运行时资源里取组件。如果元数据只写了包名，没有写导出名，渲染器拿到的是整个模块对象；React 尝试把模块对象当组件渲染，就报 <code>Card is not a react component</code>。</p><p>这类错误最迷惑人的地方是「代码明明没错」。组件本身确实没错，错的是描述：物料协议没有把「这个模块里的哪个导出」说清楚。</p><p>对应正文：<a href="./../guide/08-lowcode-engine-materials#原理拆解">原理拆解</a>。</p><h3 id="第二格-packages-与-components-的分工" tabindex="-1">第二格：packages 与 components 的分工 <a class="header-anchor" href="#第二格-packages-与-components-的分工" aria-label="Permalink to &quot;第二格：packages 与 components 的分工&quot;">​</a></h3><ul><li><strong><code>assets.packages</code></strong>：运行时资源清单。回答「这个包从哪加载、全局变量叫什么、有哪些 CSS」。它只关心资源，不关心组件。</li><li><strong><code>assets.components</code></strong>：组件元数据清单。回答「有哪些组件、标题是什么、怎么分组、有哪些属性、用什么 Setter」。</li></ul><p>两者是并列关系，不是包含关系。把组件元数据塞进 <code>packages[].components</code>，引擎的 <code>assetsTransform</code> 读不到，典型报错是 <code>Cannot read properties of undefined (reading &#39;components&#39;)</code>。正确写法是顶层同时给 <code>packages</code> 和 <code>components</code>，让资源与描述各归各位。</p><h3 id="第三格-setter-的双向协议" tabindex="-1">第三格：Setter 的双向协议 <a class="header-anchor" href="#第三格-setter-的双向协议" aria-label="Permalink to &quot;第三格：Setter 的双向协议&quot;">​</a></h3><p>Setter 接收 <code>value</code>，通过 <code>onChange</code> 把新值写回节点。它是一个受控组件，但不是业务组件：它不负责渲染订单摘要，只负责编辑某个属性。</p><p>自定义 Setter 的注册入口是 <code>ctx.setters.registerSetter({ LabToneSetter })</code>，元数据里用 <code>setter: { componentName: &quot;LabToneSetter&quot; }</code> 引用。两条链路必须同时成立：注册表里有这个 Setter，元数据里引用了这个 Setter。缺前者，右栏空白；缺后者，Setter 永远不会被调用。</p><h3 id="第四格-物料三件套" tabindex="-1">第四格：物料三件套 <a class="header-anchor" href="#第四格-物料三件套" aria-label="Permalink to &quot;第四格：物料三件套&quot;">​</a></h3><ol><li><strong>组件实现</strong>：真实的 React 组件，决定运行时长什么样；</li><li><strong>元数据</strong>：<code>npm</code>、<code>props</code>、<code>setter</code>、分组，决定设计器怎么展示与编辑；</li><li><strong>运行时资源</strong>：<code>library</code> 与 <code>urls</code>，决定渲染器从哪里加载它。</li></ol><p>三件套齐全，物料才是可分发资产：可以放进物料市场，可以被另一个项目引用，可以被出码器还原成 import 语句。只有组件实现，那只是一段业务代码，不是物料。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong><code>npm</code> 只写 <code>package</code> 和 <code>version</code></strong>：必须补 <code>exportName</code> 与 <code>destructuring</code>，否则渲染器取到模块对象。</li><li><strong>把 <code>components</code> 写进 <code>packages[]</code></strong>：引擎只读顶层 <code>components</code>，层级错一次，排查半天。</li><li><strong>Setter 只注册不引用</strong>：元数据里要写 <code>setter.componentName</code>，否则右栏不会出现。</li><li><strong>自定义组件撑爆容器</strong>：Next Card 内容区高度有限，组件过高会出现「展开」，应先缩小尺寸再排查协议。</li><li><strong>改完物料不刷新 iframe</strong>：模拟器缓存旧资源，改完 <code>lab-materials.js</code> 需要整页刷新。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. `assets.packages` 与 `assets.components` 各自回答什么问题？</b></summary><p><code>packages</code> 回答「运行时资源从哪来」：包名、版本、全局变量名、资源 URL、CSS。<code>components</code> 回答「有哪些组件、怎么描述」：组件名、标题、分组、属性、Setter、<code>npm</code> 导出信息。两者并列，不能互相嵌套。</p></details><details><summary><b>2. 为什么 `npm` 里必须写 `exportName` 和 `destructuring`？</b></summary><p>渲染器需要知道从模块的哪个导出取组件，以及这个导出是否需要解构。只写包名时，渲染器拿到整个模块对象，React 会报「不是 React 组件」。<code>exportName</code> 指定导出名，<code>destructuring: true</code> 表示按解构方式取。</p></details><details><summary><b>3. 自定义 Setter 要满足哪两个条件才会出现在右栏？</b></summary><p>第一，通过 <code>ctx.setters.registerSetter</code> 注册到 Setter 注册表；第二，组件元数据的属性里用 <code>setter: { componentName: &quot;...&quot; }</code> 引用它。注册与引用缺一不可。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./../guide/08-lowcode-engine-materials">第 08 章正文</a></li><li><a href="./../guide/09-lowcode-engine-plugins">第 09 章 · 插件机制</a></li><li><a href="./../appendix/glossary">术语表</a></li></ul>',26)])])}const u=o(c,[["render",d]]);export{g as __pageData,u as default};
